<?php $pageTitle='Penjamin Pasien'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Administrator SIMRS']);$msg='';$error='';$patients=$pdo->query("SELECT id,medical_record_no,name FROM patients ORDER BY name")->fetchAll();
if(isset($_POST['verify'])){try{$id=(int)$_POST['patient_id'];$payer=trim($_POST['payer']??'BPJS');$num=trim($_POST['number']??'');$p=$pdo->prepare('SELECT * FROM patients WHERE id=?');$p->execute([$id]);$patient=$p->fetch();if(!$patient)throw new RuntimeException('Pasien tidak ditemukan.');if($payer==='Pribadi'){$status='SELF PAY';$elig='Pembayaran Mandiri';}else{$digits=preg_replace('/\D/','',$num);$status=strlen($digits)>=8?'AKTIF':'PERLU VERIFIKASI';$elig=$status==='AKTIF'?'Layanan Rawat Jalan':'Perlu pemeriksaan lanjutan';}$pdo->prepare("INSERT INTO insurance_verifications(patient_id,payer,member_no,status,eligibility,note) VALUES(?,?,?,?,?,?)")->execute([$id,$payer,$num,$status,$elig,trim($_POST['note']??'')]);$id2=(int)$pdo->lastInsertId();audit($pdo,'VERIFY_PAYER','insurance_verifications',$id2,'Verifikasi '.$payer.' untuk '.$patient['medical_record_no']);$msg='Status penjamin diperbarui: '.$status.'.';}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query("SELECT iv.*,p.name,p.medical_record_no FROM insurance_verifications iv JOIN patients p ON p.id=iv.patient_id ORDER BY iv.id DESC LIMIT 15")->fetchAll();include 'partials/header.php'; ?>
<?php if($msg): ?><div class="alert">✓ <?=e($msg)?></div><?php endif; ?><?php if($error): ?><div class="alert error">⚠ <?=e($error)?></div><?php endif; ?>
<div class="grid"><div class="s-5"><div class="card"><div class="card-title"><div><h2>Verifikasi penjamin</h2><p>Catat status pembiayaan pasien sebelum kunjungan diproses.</p></div></div><form method="post"><label>Pasien</label><select name="patient_id" required><option value="">Pilih pasien</option><?php foreach($patients as $p): ?><option value="<?=$p['id']?>"><?=e($p['name'])?> • <?=e($p['medical_record_no'])?></option><?php endforeach; ?></select><label>Sumber pembiayaan</label><select name="payer"><option>BPJS</option><option>Asuransi</option><option>Pribadi</option></select><label>No. kepesertaan / nomor polis</label><input name="number" inputmode="numeric"><label>Catatan verifikasi</label><textarea name="note" placeholder="Hasil pemeriksaan administrasi"></textarea><button class="btn" style="width:100%;margin-top:16px">Simpan Verifikasi</button></form></div></div><div class="s-7"><div class="card"><div class="card-title"><div><h2>Riwayat penjamin</h2><p>Pencatatan terbaru untuk proses administrasi registrasi.</p></div></div><div class="table-wrap"><table><tr><th>Pasien</th><th>Penjamin</th><th>Nomor</th><th>Status</th><th>Hak Layanan</th><th>Waktu</th></tr><?php foreach($rows as $r): ?><tr><td><b><?=e($r['name'])?></b><div class="muted"><?=e($r['medical_record_no'])?></div></td><td><?=e($r['payer'])?></td><td><?=e($r['member_no']?:'—')?></td><td><span class="badge <?=str_contains($r['status'],'AKTIF')?'green':($r['status']==='SELF PAY'?'blue':'amber')?>"><?=e($r['status'])?></span></td><td><?=e($r['eligibility'])?></td><td><?=e(date('d/m/Y H:i',strtotime($r['verified_at'])))?></td></tr><?php endforeach; ?></table></div></div></div></div>
<?php include 'partials/footer.php'; ?>
